package net.civeira.phylax.features.access.tenantconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class DisabledUserEmailTemplateVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property disabled user email template of tenant config ")
  void test_disabled_user_email_template_v_o_builder() {
    Assertions.assertFalse(
        DisabledUserEmailTemplateVO.nullValue().getDisabledUserEmailTemplate().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(
        DisabledUserEmailTemplateVO.tryFrom(null).getDisabledUserEmailTemplate().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one",
        DisabledUserEmailTemplateVO.from("one").getDisabledUserEmailTemplate().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> DisabledUserEmailTemplateVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", DisabledUserEmailTemplateVO.from("one").toString());
  }
}
